const weights=Object.fromEntries(Object.entries(ITEMS).map(([k,v])=>[k,v.mass]));const cargo=()=>mass(s.inv);const cargoLimit=()=>s.trailerAttached?40:24;const energyWeight=()=>cargo()+mass(s.field.storage.bike)+(s.trailerAttached?8+s.trailer*.06+mass(s.field.storage.trailer)+storedPackMass(s):0);const dist=(x,z)=>Math.hypot(s.pos.x-x,s.pos.z-z);function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';toastTimer=4.5;}function radio(t){radioUntil=time+7;document.body.classList.add('radio-active');sound.event('radio');$('#radioText').textContent=t;}
