function resetTouchControls(){leftStick.reset();rightStick.reset();stickX=stickY=0;flightRates=[0,0,0];dragging=false;lookPointer=null;}
document.addEventListener('visibilitychange',()=>{if(document.hidden&&!paused)open('pause');});
window.addEventListener('pagehide',()=>{if(!paused)open('pause');});
$('#world').addEventListener('contextmenu',e=>e.preventDefault());
if(mobile){document.querySelectorAll('footer [data-act]').forEach(b=>{const labels={interact:'USE',bike:'BIKE',drone:'DRONE',scan:'SCAN',inventory:'PACK',map:'MAP',charger:'CHARGER',reserve:'RESERVE'};b.textContent=labels[b.dataset.act];b.setAttribute('aria-label',labels[b.dataset.act]);});}

function transferReserve(){sound.event('use');if(!s.trailerAttached){toast('Attach the trailer to transfer reserve energy.');return;}const n=Math.min(10,s.trailer,100-s.battery);if(n<=.01){toast(s.trailer<.01?'Trailer depleted. Harvest at a receiver.':'Bike battery full.');return;}s.trailer-=n;s.battery+=n;toast('Trailer → bike: '+n.toFixed(1)+'% transferred.');}
function toggleTrailer(){sound.event('use');if(s.mode==='drone'){toast('Return to your bike first.');return;}if(s.trailerAttached){if(Math.abs(s.speed)>1){toast('Stop before unhitching the trailer.');return;}s.trailerAttached=false;toast('Trailer parked. Cargo capacity reduced to 24 kg.');}else if(dist(trailer.position.x,trailer.position.z)<8){s.trailerAttached=true;toast('Trailer attached.');}else toast('Move within 8 m of the parked trailer.');}
function startCharge(key,destination,t){sound.event('use');const capacity=destination==='trailer'?40:100;if(s[key]<=.01){toast('Source depleted.');return;}if(s[destination]>=capacity-.01){toast(destination==='trailer'?'Trailer reserve full.':'Bike battery full.');return;}if(s.chargeHeat>70){toast('Coupler hot. Wait for cooling before reconnecting.');return;}s.speed=0;s.harvesting={key,destination,x:t.x,z:t.z,y:t.y,total:0};toast(destination==='trailer'?'PERCHED · collecting into trailer reserve':'CONNECTED · charging bike · stay near source');}
function stopCharge(message){sound.event('use');s.harvesting=null;if(message)toast(message);}
function updateCharge(dt){s.chargeHeat=Math.max(0,s.chargeHeat-dt*3);const h=s.harvesting;if(!h)return;const d=Math.hypot(s.pos.x-h.x,s.pos.y-h.y,s.pos.z-h.z);if(d>9){stopCharge('Connection lost: moved out of range.');return;}if(h.destination==='trailer'&&(!s.trailerAttached||s.mode!=='drone'||s.droneType!=='engineer'||Math.hypot(trailer.position.x-h.x,trailer.position.z-h.z)>240)){stopCharge('Trailer link lost.');return;}const cap=h.destination==='trailer'?40:100,rate=h.key==='ev'?2.8:h.key==='solarEnergy'?2.1:3.2,n=Math.max(0,Math.min(dt*rate,s[h.key],cap-s[h.destination]));s[h.key]-=n;s[h.destination]+=n;h.total+=n;s.chargeHeat+=n*2.4*difficultyFactor();if(h.key==='solarEnergy')s.solar=true;if(s.chargeHeat>=90){stopCharge('Thermal cut-off. Let the coupler cool.');return;}if(s[h.key]<=.01||s[h.destination]>=cap-.01)stopCharge('Charge complete. Disconnecting safely.');}
function findPower(paid=false){if(s.leg===3){s.powerTarget='l3supply';s.scanned=true;s.scanTime=18;toast(s.leg3Supply?'Station reserve used. Generate fuel or solar power while stopped.':'Reserve battery station marked. One emergency pack remains.');return;}if(s.leg===2){s.scanned=true;s.powerTarget='l2hydro';toast(s.intakeCleared?'Flowing water at the turbine dock. Park the trailer on the bank.':'River signature found. Release the elevated intake with your drone.');return;}if(!paid&&s.drone<2){toast('Recharge your drone to search for power.');return;}if(!paid)s.drone-=2;s.scanned=true;s.scanTime=18;const known=sites.filter(p=>['ev','solar','grid','line'].includes(p.id)&&s[{ev:'ev',solar:'solarEnergy',grid:'gridEnergy',line:'lineEnergy'}[p.id]]>.01).sort((a,b)=>dist(a.x,a.z)-dist(b.x,b.z));const p=known[0];if(p){s.powerTarget=p.id;radio('CHARGER: '+p.name+', '+Math.round(dist(p.x,p.z)*2)+' meters. '+(p.id==='line'?'Engineer module required.':p.id==='solar'?'Controller required.':'Signature acquired.'));toast('Power route marked: '+p.name);}else toast('No remaining energy signatures. Recondition salvaged cells.');}
function updateRig(dt){if(npc.userData.head){npc.userData.head.rotation.y=Math.sin(time*.37)*.07;npc.userData.head.rotation.x=Math.sin(time*.8)*.018;}if(!npc.userData.ambient)for(const [i,arm]of(npc.userData.arms||[]).entries())arm.rotation.x=Math.sin(time*.85+i)*.035;for(const rig of [bike,trailer])for(const wheel of rig.userData.wheels||[])wheel.rotation.x-=dt*(s.mode==='bike'?s.speed:0)/.48;for(const {hinge,side} of trailer.userData.panels){const target=s.generator==='solar'&&Math.abs(s.speed)<.5?side*.12:-side*Math.PI/2;hinge.rotation.z+=(target-hinge.rotation.z)*Math.min(1,dt*5);}trailer.userData.indicator.visible=s.generator!=='off'&&Math.abs(s.speed)<.5;bike.position.y=s.mode==='bike'?s.pos.y-1.7:bike.position.y;if(s.trailerAttached){const target=bike.position.clone().add(new T.Vector3(Math.sin(bike.rotation.y)*3.4,0,Math.cos(bike.rotation.y)*3.4));trailer.position.lerp(target,Math.min(1,dt*8));trailer.position.y=s.leg===1?Math.max(heightAt(trailer.position.x,trailer.position.z),relayFloor(trailer.position.x,trailer.position.z,trailer.position.y+1.7)):heightAt(trailer.position.x,trailer.position.z);trailer.rotation.y=bike.rotation.y;}fleet.update(dt,s,trailer,bike,camera,{reducedMotion:settings.reduceMotion});gun.visible=s.mode==='foot';gun.position.z=flash>0?.045:0;cockpit.position.y=settings.bob&&!settings.reduceMotion?Math.sin(time*8)*Math.abs(s.speed)*.0003:0;}
function updateReferenceHUD(){$('#reserveValue').textContent=Math.round(s.trailer/40*100)+'%';$('#reserveBar').style.width=s.trailer/40*100+'%';$('#reserveHint').textContent=s.trailerAttached?'TAP TO TRANSFER':'TRAILER PARKED';const h=s.harvesting;$('#chargeTitle').textContent=h?'ENERGY TRANSFER':'CHARGING AVAILABILITY';const p=sites.filter(p=>['ev','solar','grid','line'].includes(p.id)).sort((a,b)=>dist(a.x,a.z)-dist(b.x,b.z))[0];$('#chargeSource').textContent=h?h.key==='lineEnergy'?'PERCHED / RECEIVING':'CONNECTED / RECEIVING':p.name;$('#chargeDetail').textContent=h?h.total.toFixed(1)+' UNITS RECOVERED':Math.round(dist(p.x,p.z)*2)+' M · '+(s[{ev:'ev',solar:'solarEnergy',grid:'gridEnergy',line:'lineEnergy'}[p.id]]<.01?'DEPLETED':p.id==='solar'&&!s.controller?'CONTROLLER NEEDED':p.id==='line'&&!s.engineerBuilt?'ENGINEER NEEDED':p.id==='grid'&&(!s.relay||!s.interface)?'LOCKED':'SIGNATURE LIVE');$('#chargeHeat').textContent='COUPLER '+Math.round(s.chargeHeat)+'° / '+(h?'ACTIVE':'IDLE');$('#chargeProgress').style.width=(h?Math.min(100,h.total/30*100):0)+'%';$('#droneReadout').textContent=s.mode==='drone'?s.droneType.toUpperCase()+' / ALT '+(s.pos.y-heightAt(s.pos.x,s.pos.z)).toFixed(1)+' M':(s.scanTime||0)>0?'SCOUT / SEARCHING':'SCOUT / DOCKED';$('#ammoReadout').textContent=s.ammo+' ROUNDS · HULL '+Math.max(0,Math.round(s.hp))+'%';drawInstruments(cockpit.userData.display,s);}

// Expedition menus, device-local saves and field systems.
let storyPage=0,storyReturn='start',storyReadThisSession=false,manualSection='start',newTutorialChoice=null;
function beginPrologue(target='start'){storyReturn=target;storyPage=0;menuNotice='';open('prologue');}
function finishPrologue(){storyReadThisSession=true;try{localStorage.setItem('gridrunner.prologue.v1','seen');}catch{}if(storyReturn==='new'){newExpedition(newTutorialChoice??settings.tutorialEnabled,true);newTutorialChoice=null;}else open(storyReturn);}
function requestExpedition(){if(storyReadThisSession){newExpedition(newTutorialChoice??settings.tutorialEnabled,true);newTutorialChoice=null;}else beginPrologue('new');}
const defaults={narration:true,tutorialEnabled:true,randomEnvironment:true,droneLamp:false,sensorMode:'visible',hudMode:'field',scanOverlay:true,nightVision:false,sunHour:13.5,movingSun:false,autoWeather:false,dayMinutes:12,droneFlight:'stabilized',droneStickLayout:'mode2',gamepad:true,gamepadDeadzone:.18,gamepadSensitivity:1,gamepadInvert:false,chaseDistance:1,chaseHeight:1,cameraSmoothing:8,leanInfluence:.5,droneSensitivity:1,hudIntensity:1,visor:true,reduceMotion:false,graphics:mobile?'LOW':'HIGH',cameraMotion:.45,speedFov:.6,stabilization:true,headlights:true,interference:true,ambience:.65,master:.65,effects:.7,music:.25,difficulty:'survival',compass:true,navigation:false,quest:true,charging:false,radio:true,reticle:true,markers:true,dronePanel:false,bob:false,invert:false,sensitivity:1,fov:72,weather:'dusk',autosave:true};
let settings={...defaults},started=false,pedalToggle=false,autoClock=0,menuNotice='';
try{const saved=JSON.parse(localStorage.getItem('gridrunner.settings')||'{}');for(const k of Object.keys(defaults)){if(typeof saved[k]===typeof defaults[k])settings[k]=saved[k];}}catch{}
if(settings.weather==='dusk'&&settings.sunHour===17.5&&!settings.movingSun)settings.sunHour=13.5;
settings.fov=clamp(settings.fov,60,100);settings.sensitivity=clamp(settings.sensitivity,.4,2);if(!['dusk','night','heat','sandstorm','rain','storm','blackout'].includes(settings.weather))settings.weather='dusk';
randomEnvironment(settings);
const slots=['auto','manual1','manual2','manual3'];
const slotLabel=k=>k==='auto'?'Autosave':'Manual save '+k.slice(-1);
function getSave(k){try{const raw=localStorage.getItem('gridrunner.save.'+k);return raw?validateSave(JSON.parse(raw)):null;}catch{return null;}}
function snapshot(){syncSquad(s);return {version:SAVE_VERSION,savedAt:Date.now(),state:{...s,pos:s.pos.toArray(),speed:0,harvesting:null,scanTime:0},bike:bike.position.toArray(),trailer:trailer.position.toArray(),origin:droneOrigin?{...droneOrigin,pos:droneOrigin.pos.toArray()}:null,crates:crates.map(c=>!!c.done),crateContents:crates.map((c,i)=>c.done?{}:{...(c.items||CRATE_ITEMS[i])}),enemies:enemies.map(e=>({x:e.x,z:e.z,hp:e.hp}))};}
function writeSave(k,quiet=false){if(flightSession){if(!quiet)toast('Flight Yard is a practice session. Return to the expedition to save.');return false;}if(!started||s.dead){if(!quiet)toast('Start or resume a living expedition before saving.');return false;}try{const record=validateSave(snapshot());localStorage.setItem('gridrunner.save.'+k,JSON.stringify(record));if(!quiet){sound.event('save');menuNotice=slotLabel(k)+' saved on this device.';toast(menuNotice);}return true;}catch{menuNotice='Could not save. Browser storage may be full or blocked. Export a backup from Save / Load.';if(!quiet)toast(menuNotice);return false;}}
function restore(r){flightSession=null;fieldJob=null;activeField=null;validateSave(r);const fresh=initial();for(const k of Object.keys(fresh))if(k!=='pos'&&k in r.state)fresh[k]=r.state[k];fresh.pos=new T.Vector3().fromArray(r.state.pos);fresh.harvesting=null;fresh.speed=0;s=fresh;s.intro=migrateIntro(s.intro);if(s.intro.stage!=='line'&&s.mode==='bike'&&!s.intro.mounted){s.mode='foot';}bike.position.fromArray(r.bike);trailer.position.fromArray(r.trailer);bike.rotation.y=s.yaw;trailer.rotation.y=s.yaw;droneOrigin=r.origin?{...r.origin,pos:new T.Vector3().fromArray(r.origin.pos)}:null;crates.forEach((c,i)=>{c.done=r.crates[i];c.items={...r.crateContents[i]};c.mesh.visible=!c.done;});enemies.forEach((e,i)=>{Object.assign(e,r.enemies[i]);e.mesh.rotation.set(0,0,e.hp<=0?Math.PI/2:0);e.mesh.position.set(e.x,e.hp<=0?.3:0,e.z);});started=true;autoClock=0;pedalToggle=false;nearest=null;keys={};menuNotice='Expedition restored.';queueSwarmAircraft();hud();}
function newExpedition(tutorial=settings.tutorialEnabled,storyMode=false){flightSession=null;campaignReturn=null;fieldJob=null;activeField=null;s=initial(tutorial);s.story=createStoryCampaign(storyMode?"story":"legacy");fieldBeat=null;storyNotice="";droneOrigin=null;crates.forEach((c,i)=>{c.done=false;c.items={...CRATE_ITEMS[i]};c.mesh.visible=true;});enemies.forEach(e=>{e.x=e.home[0];e.z=e.home[1];e.hp=75;e.mesh.rotation.set(0,0,0);e.mesh.position.set(e.x,0,e.z);});bike.position.set(0,0,15);bike.rotation.y=0;trailer.position.set(0,0,18.2);trailer.rotation.y=0;pedalToggle=false;started=true;autoClock=0;nearest=null;radio('CHARGER: On foot. Motorcycle is ahead. Mount up.');hud();play();}
function applySettings(){if(!['mode2','classic'].includes(settings.droneStickLayout))settings.droneStickLayout='mode2';resetTouchControls();syncSensorSelection(settings,sensorOwner());if(!['field','navigation','systems'].includes(settings.hudMode))settings.hudMode='field';document.body.dataset.hudMode=settings.hudMode;document.body.dataset.sensor=settings.sensorMode;settings.sunHour=clamp(Number(settings.sunHour)||0,0,23.9);settings.dayMinutes=clamp(Number(settings.dayMinutes)||12,2,60);if(!['stabilized','acro'].includes(settings.droneFlight))settings.droneFlight='stabilized';settings.gamepadDeadzone=clamp(Number(settings.gamepadDeadzone)||.18,.05,.4);settings.gamepadSensitivity=clamp(Number(settings.gamepadSensitivity)||1,.25,2.5);for(const [k,a,b]of [['chaseDistance',.6,1.7],['chaseHeight',.5,1.7],['cameraSmoothing',3,18],['leanInfluence',0,1],['droneSensitivity',.4,2],['hudIntensity',.25,1]])settings[k]=clamp(Number(settings[k])||a,a,b);document.body.style.setProperty('--hud-intensity',settings.hudIntensity);for(const k of ['master','effects','music','ambience','cameraMotion','speedFov'])settings[k]=clamp(Number(settings[k])||0,0,1);if(!['explorer','standard','survival'].includes(settings.difficulty))settings.difficulty='survival';sound.setLevels({master:settings.master,effects:settings.effects,music:settings.music,ambience:settings.ambience});for(const k of ['compass','navigation','quest','charging','radio','reticle','markers','dronePanel'])document.body.classList.toggle('hide-'+k,!settings[k]);camera.fov=settings.fov;camera.updateProjectionMatrix();const sky={dusk:[0xa9a29c,.001,1.05,2.3],night:[0x091520,.002,.55,.18],heat:[0xc8b7a1,.0011,1.3,3],sandstorm:[0x8b7860,.009,.85,.9]}[settings.weather]||[0x73808a,.003,1.05,1.3];scene.background.setHex(sky[0]);scene.fog.color.setHex(sky[0]);scene.fog.density=sky[1];renderer.toneMappingExposure=sky[2];sun.intensity=sky[3];if(!PRESETS[settings.graphics])settings.graphics=defaults.graphics;fleet.setQuality(settings.graphics);immersion.apply(settings,s.leg);presence.apply(settings);try{localStorage.setItem('gridrunner.settings',JSON.stringify(settings));}catch{menuNotice='Settings apply now but could not be stored on this device.';}}
function updateExpedition(dt){advanceStoryOperations(s,dt);if(!flightSession)advanceStoryLog(s);if(s.leg===1&&dist(RELAY_SITE.x,RELAY_SITE.z)<35)s.relayHouse.visited=true;updateFieldJob(dt);s.puzzleLock=Math.max(0,s.puzzleLock-dt);updateSecurity(dt);for(const stripe of leg2World.water.children){stripe.position.z+=dt*(s.intakeCleared?9:2);if(stripe.position.z>-2105)stripe.position.z=-2630;}for(const lamp of leg2World.lights)lamp.material.color.setHex(s.hydroRestored?0x89f7bb:0x223b3a);const g=generationStep(s.generator,{fuel:s.fuel,reserve:s.trailer,daylight:environmentState(settings,s.elapsed).daylight>.15&&!environmentState(settings,s.elapsed).black,stopped:Math.abs(s.speed)<.5&&s.mode!=='drone',flowing:hydroAvailable(s,trailer.position)},dt);s.trailer+=g.gain;s.fuel=Math.max(0,s.fuel-g.fuelUsed);if(s.mode!=='bike')s.stamina=Math.min(100,s.stamina+dt*9);autoClock+=dt;if(autoClock>=60){autoClock=0;if(settings.autosave)writeSave('auto',true);}}
const navItems=[['flightyard','Flight Yard'],['locations','Settlements'],['map','Map'],['journal','Journal'],['inventory','Pack / Craft'],['rig','Bike / Trailer'],['drones','Drones'],['saves','Save / Load'],['settings','Settings'],['guide','Field manual']];
