 $('#scanToggle').setAttribute('aria-pressed',String(settings.scanOverlay));$('#scanToggle').textContent='K / SCAN '+(settings.scanOverlay?'ON':'OFF');$('#visionToggle').setAttribute('aria-pressed',String(settings.nightVision));$('#visionToggle').textContent='N / NV '+(settings.nightVision?'ON':'OFF');$('#environmentBtn').textContent='O / '+(e.black?'BLACKOUT':String(Math.floor(e.hour)).padStart(2,'0')+':'+String(Math.floor(e.hour%1*60)).padStart(2,'0'))+' · '+e.weather.toUpperCase();
 $('#opticsBar').hidden=!started;$('#flightStrip').hidden=!started||s.mode!=='drone';$('#flightStrip').textContent=(FLEET.find(r=>r.id===s.droneType)?.code||s.droneType)+' / '+d.mode+' · ALT '+d.altitude.toFixed(1)+' m · '+d.speed.toFixed(1)+' m/s · BAT '+Math.round(s.drone)+'%';
