 $('#flightHelp').innerHTML='<b>'+settings.droneFlight.toUpperCase()+' / '+(sticks?(mode2?'LS lift / yaw · RS '+(settings.droneFlight==='acro'?'pitch / roll':'forward / strafe'):'LS drive / roll · RS pitch / yaw'):'W/S drive · A/D '+(settings.droneFlight==='acro'?'roll':'strafe')+' · mouse / arrows pitch / yaw')+'</b><span>'+(sticks&&mode2?'Centered lift = hover thrust · ':'SPACE / SHIFT or D-pad ↑↓ lift · ')+'2 HOLD · H / LB camera</span>';
 document.body.dataset.droneSticks=settings.droneStickLayout;
