function renderLocations(){const near=settlementWorld.near(s);$('#overlay').dataset.screen='locations';$('#panel').innerHTML=nav()+title('ROADSIDE NETWORK','Settlements & services')+`<p class="lead">A place to stop. A reason to keep going.</p><div class="locationGrid">${SETTLEMENTS.filter(p=>p.leg===s.leg).map(p=>{const residents=RESIDENTS.filter(n=>n.site===p.id),distance=dist(p.x,p.z);return `<article class="locationCard"><span class="missionIndex">${p.style.toUpperCase()} / ${Math.round(distance)} m</span><h3>${p.name}</h3><p>${p.style==='garage'?'Covered work bays, spare components and local repair knowledge.':p.style==='diner'?'Shelter, roadside conversation and a small barter stock.':'Former worker housing, personal belongings and a place out of the wind.'}</p><div class="chips">${residents.map(n=>`<span>${n.name} · ${s.residents[n.id]?.met?'CONTACTED':'UNMET'}</span>`).join('')||'<span>UNSTAFFED</span>'}</div><button data-location="${p.id}">MARK ON MAP</button>${distance<26&&s.mode!=='drone'?'<button data-local-rest>REST UNDER COVER</button><button data-nav="inventory">OPEN PACK / WORKSHOP</button>':''}</article>`;}).join('')}</div><p class="hint">Walk into the open-front rooms. Approach a resident and press E / A / USE to talk or barter. ${near?.d<26?'Rest restores stamina only; supplies and charge remain finite.':'Nearby services become available inside the forecourt.'}</p>`;}
$('#panel').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.location){const p=SETTLEMENTS.find(p=>p.id===b.dataset.location);if(p){const tag={id:p.id,name:p.name,kind:'OBJECTIVE',x:p.x,y:2,z:p.z,leg:p.leg,at:s.elapsed};s.discoveries=[...s.discoveries.filter(t=>t.id!==p.id),tag];toast('Settlement retained on your map.');open('map');}}if(b.hasAttribute('data-local-rest')){const p=settlementWorld.near(s);if(p?.d<26&&s.mode!=='drone'){s.stamina=100;toast('Rested under cover / stamina restored.');}}if(b.dataset.residentTopic){residentTopic=b.dataset.residentTopic;renderPanel();}});

