function lootTarget(){return activeLoot?.kind==='crate'?crates[activeLoot.index]:s.field.world.find(p=>p.id===activeLoot?.id);}
function renderLootWindow(){const c=lootTarget();document.body.classList.add('menu-open');$('#overlay').dataset.screen='loot';$('#panel').innerHTML=lootWindow(c?.items||{},activeLoot?.kind==='crate'?'FIELD SALVAGE':String(c?.table||'Salvage').toUpperCase(),cargo(),cargoLimit(),itemSymbol,ITEMS,menuNotice);if(activeLoot?.kind==='crate'&&activeLoot.index===0&&introQuiet(s)){$('#panel .lootWindow').insertAdjacentHTML('afterbegin',`<div class="scoutAcquisition"><span>WORKSHOP CLUSTER / FIELD SUPPLIES</span><b>${s.intro.salvaged?'SPARES RECOVERED · SIX AIRCRAFT READY':'WIRE + CELLS FOR YOUR EXISTING FLEET'}</b><p>${s.intro.salvaged?'Your scout is ready. Close this box to begin its narrated flight guide.':'Take supplies for your workshop-built cluster. Untaken materials stay in this box.'}</p></div>`);}}
function takeLoot(id){const c=lootTarget();if(!c||s.mode==='drone'||!started||s.dead)return;let count=0;for(const key of id==='all'?Object.keys(c.items):[id]){do{const before=s.inv[key]||0;transfer(c.items,s.inv,key,1,cargoLimit());if((s.inv[key]||0)===before)break;count++;}while(id==='all');}if(activeLoot.kind==='crate'){c.done=!Object.values(c.items).some(n=>n>0);c.mesh.visible=!c.done;if(count&&activeLoot.index===INTRO_CRATE&&introQuiet(s)){const first=!s.intro.salvaged;markIntro(s,'salvaged');if(first)narrator.read('Scout recovered. Added to your fleet. Close the box to learn how to fly it.',{enabled:settings.narration,volume:settings.master,clip:null});}if(count&&activeLoot.index===2&&!s.towerCode){s.towerCode=true;radio('TECHNICIAN NOTE: Tower authentication token recovered.');}}menuNotice=count?'Transferred '+count+' item'+(count===1?'':'s')+'. Remaining items stay here.':'No room for that item. Store supplies on the bike or trailer first.';sound.event(count?'use':'ui');renderPanel();}
