$('#panel').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.loot)takeLoot(b.dataset.loot);if(b.dataset.brief){if(b.dataset.brief==='back'){briefPage=Math.max(0,briefPage-1);renderPanel();}else if(b.dataset.brief==='skip'){finishEquipmentLesson();}else{const list=screen==='scoutintro'?SCOUT_LESSONS:EQUIPMENT_LESSONS;if(briefPage>=list.length-1)finishEquipmentLesson();else{briefPage++;renderPanel();}}}});
function tickSquad(dt){const squad=syncSquad(s);for(const [id,r]of Object.entries(squad)){if(!storyOwns(s,id)||storyStation(s,id))continue;if(id===s.droneType||r.system.mode==='DOCK'&&!hasLiveTask(r)&&!(id==='engineer'&&s.fleetPolicy?.enabled))continue;preparePackDelivery(r,trailerDock());const result=updateDrone(r.system,dt,{home:droneHome(),followHome:fleetAnchor().pos,yaw:r.task?.kind==='LINE'&&r.task.state==='RUNNING'?0:fleetAnchor().yaw,taskTarget:taskDestination(r),swarmPeers,idleMotion:!settings.reduceMotion,formationSpeed:s.fleetFormation==='BUZZ PASS'?10:Infinity,relayNodes:[...activeRelayNodes(squad),...airborneRelays(squad)],battery:r.battery,type:r.type,swarmId:id,payloadKg:aircraftPayload(id),terrain:heightAt,solids:spatial,storm:['sandstorm','storm'].includes(environmentState(settings,s.elapsed).weather),jammed:s.leg===3&&r.system.pos[2]<-3950&&r.system.pos[2]>-4200,difficulty:difficultyFactor(),wind:environmentState(settings,s.elapsed).wind,elapsed:s.elapsed,floorZ:s.leg===3?-4720:s.leg===2?-3200:-1600,formationOffset:liveSwarmOffset(id,r)});r.battery=result.battery;advanceFleetJob(r,dt,result.events);for(const event of result.events)if(['dock','landing','return'].includes(event))toast(id.toUpperCase()+' / '+r.system.reason);}}

function updateFieldControls(){updateStoryHUD();updateAdminFleetHUD();updateSwarmFieldHUD();if(settings.sensorOwner!==sensorOwner())applySettings();const bar=$('#fieldControls');if(!bar)return;bar.hidden=!started||paused;$('#hudModeToggle').textContent='HUD / '+settings.hudMode.toUpperCase();$('#sensorCycle').textContent='B / '+(s.mode==='drone'?s.droneType.toUpperCase():'VISOR')+' / '+settings.sensorMode.toUpperCase();$('#lampToggle').textContent='L / LIGHT '+(settings.droneLamp?'ON':'OFF');$('#lampToggle').setAttribute('aria-pressed',String(settings.droneLamp));$('#lampToggle').hidden=s.mode!=='drone';$('#squadButton').textContent='FLEET / '+Object.values(syncSquad(s)).filter(r=>!['DOCK','LANDED','RELAY','PERCHED'].includes(r.system.mode)).length+' AIR · '+s.fleetFormation;const rf=$('#rfReadout');rf.hidden=settings.sensorMode!=='rf'||paused||!started;if(!rf.hidden){const origin=s.mode==='drone'?s.droneSystem.pos:s.pos.toArray();const sources=[...sites.filter(p=>(p.id.startsWith('l3')?s.leg===3:p.id.startsWith('l2')?s.leg===2:s.leg===1)&&/relay|tower|grid|line|hydro/.test(p.id)).map(p=>({name:p.name,pos:[p.x,p.y||2,p.z]})),...Object.entries(s.squad).filter(([id,r])=>id!==s.droneType&&r.system.mode!=='DOCK').map(([id,r])=>({name:id.toUpperCase(),pos:r.system.pos}))].map(p=>({...p,d:Math.hypot(...p.pos.map((v,i)=>v-origin[i]))})).filter(p=>p.d<620).sort((a,b)=>a.d-b.d).slice(0,4);rf.innerHTML='<b>RF / PASSIVE SIGNALS</b>'+sources.map(p=>{const strength=clamp(100-p.d/6.2-obstruction(origin,p.pos,solids)*18,0,100);return '<span>'+esc(p.name)+' · '+Math.round(strength)+'% · '+Math.round((Math.atan2(p.pos[0]-origin[0],origin[2]-p.pos[2])*180/Math.PI+360)%360)+'°</span>';}).join('')+(sources.length?'':'<span>No carrier in range.</span>');}}
