function renderEquipmentLesson(){const scout=screen==='scoutintro',list=scout?SCOUT_LESSONS:EQUIPMENT_LESSONS;briefPage=clamp(briefPage,0,list.length-1);const lesson={...list[briefPage]};const key=k=>(remap[k]||k).toUpperCase();if(lesson.target==='bike')lesson.detail=`${key('w')} / ${key('s')} · accelerate / brake. ${key('p')} · pedal. ${key('f')} · mount.`;if(scout&&briefPage===1)lesson.detail=settings.droneStickLayout==='mode2'&&['gamepad','touch'].includes(controller.device)?`LEFT · lift / yaw. RIGHT · ${settings.droneFlight==='acro'?'pitch / roll':'forward / strafe'}. ${controller.device==='gamepad'?'RB recall · LB camera · X scan.':'DRONE recall · SCAN discovers.'}`:controller.device==='gamepad'?'LS moves · D-pad up/down lifts · RB recalls · LB camera · X scans.':mobile?'Left stick moves · drag to look · RISE / DESCEND lift · DRONE recalls · SCAN discovers.':`${key(' ')} / ${key('shift')} · rise / descend. ${key('r')} · scan. ${key('q')} · recall. ${key('h')} · camera.`;document.body.classList.add('menu-open');$('#overlay').dataset.screen=screen;$('#panel').innerHTML=lessonPanel(lesson,briefPage,list.length,settings.narration);narrator.read(lesson.title+' '+lesson.text,{enabled:settings.narration,volume:settings.master,clip:scout&&briefPage===0?null:(scout?'scout-':'equipment-')+briefPage});}
function finishEquipmentLesson(){const scout=screen==='scoutintro';if(scout)s.intro.scoutBriefed=true;else s.intro.trailerBriefed=true;const launch=scout&&scoutLaunchAfter;scoutLaunchAfter=false;play();if(launch)issueDrone('MANUAL');}
