function decorateStory(){const p=PROLOGUE[storyPage];$('#panel .prologue-page').insertAdjacentHTML('afterbegin',`<div class="storyLandscape" aria-hidden="true"><i class="storyMoon"></i><div class="storyHills"></div><div class="storyPylon"></div><div class="storySignal"></div></div>`);$('#panel .prologue-controls').insertAdjacentHTML('beforebegin',`<div class="narratorControls"><button data-tutorial="listen">▶ LISTEN</button><button data-tutorial="mute" aria-pressed="${settings.narration}">${settings.narration?'MUTE NARRATOR':'NARRATOR OFF'}</button><button data-tutorial="skipStoryTutorial">SKIP THIS INTRODUCTION</button><small>${narrator.available?'Narrated transmission · captions always visible':'Narration unavailable on this device · captions available'}</small></div>`);narrator.read(p.title.replace('\n',' ')+'. '+p.text.join(' '),{enabled:settings.narration,volume:settings.master,clip:storyPage===0?'story-0':null});}
function renderMaraDialogue(){return `<section class="maraDialogue"><div class="contactIdentity">${characterPortrait('Mara')}<span class="eyebrow">FIELD ENGINEER / ROADSIDE CAMP</span><h2>Mara</h2><p>Keeper of the southern line.</p></div><div class="contactWords"><span class="eyebrow">104.7 MHz / A CHANGED MESSAGE</span><h2>“Electricity always leaves a trail.”</h2><p class="lead">That tower has been calling for twelve years. Yesterday, the message changed.</p><div class="maraClues"><article><span>01 / RECOVER</span><h3>The stranded EV</h3><p>West of the road. Its emergency pack still holds charge. Start there.</p></article><article><span>02 / REPAIR</span><h3>The solar yard</h3><p>Search the crates for electronics and wire. Repair a controller in your Workshop.</p></article><article><span>03 / RECONNECT</span><h3>The substation</h3><p>Restore your grid coupler. Fly up to the rooftop relay to release the charge cabinet.</p></article></div><aside class="contactGift">RECEIVED FROM MARA · 2 electronics · 2 wire · 2 steel · repair schematics</aside><p class="hint">Raiders patrol the highway. Scout the road before you ride. Your journal keeps the route.</p><button class="primary" data-panel="play">I’LL FOLLOW THE LINE →</button></div></section>`;}
$('#panel').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.panel==='play'&&screen==='loot'&&introQuiet(s)&&s.intro.salvaged&&!s.intro.scoutBriefed){e.stopImmediatePropagation();briefPage=0;scoutLaunchAfter=false;open('scoutintro');return;}if(b.dataset.rigFocus){e.stopImmediatePropagation();rigFocus=b.dataset.rigFocus;renderPanel();return;}const a=b.dataset.tutorial;if(!a)return;e.stopImmediatePropagation();narrator.unlocked=true;if(a==='mute'){settings.narration=!settings.narration;narrator.stop();applySettings();renderPanel();}if(a==='listen'){settings.narration=true;narrator.stop();applySettings();renderPanel();}if(a==='skip')skipTutorial();if(a==='skipStoryTutorial'){if(storyReturn==='new')newTutorialChoice=false;narrator.stop();finishPrologue();}if(a==='equipment'){briefPage=0;open('bikeintro');}if(a==='trailer'){briefPage=1;open('trailerintro');}if(a==='scout'){briefPage=0;scoutLaunchAfter=false;open('scoutintro');}},{capture:true});
window.addEventListener('pointerdown',()=>{narrator.unlocked=true;},{capture:true});window.addEventListener('keydown',()=>{narrator.unlocked=true;},{capture:true});document.addEventListener('visibilitychange',()=>{if(document.hidden)narrator.stop();});

// Warm shader variants while the opening is paused, after assets have settled.
let warmSignature='',warmBusy=false;const warmedTextures=new WeakSet();
function warmOpening(){if(!paused||warmBusy||settings.graphics==='LOW'||!renderer.compileAsync)return;const kit=relayWorld.kit;const signature=settings.graphics+':'+kit.slots.filter(r=>r.loaded).length+':'+Object.values(fleet.records).filter(r=>r.loaded).length;if(signature===warmSignature)return;let pending=false,next=null;scene.traverse(o=>{for(const m of Array.isArray(o.material)?o.material:o.material?[o.material]:[])for(const key of ['map','normalMap','roughnessMap','metalnessMap','aoMap','alphaMap','emissiveMap']){const t=m[key];if(!t?.isTexture||t.isRenderTargetTexture||warmedTextures.has(t))continue;if(!t.image?.width)pending=true;else if(!next)next=t;}});if(next&&renderer.initTexture){renderer.initTexture(next);warmedTextures.add(next);return;}if(pending)return;warmSignature=signature;warmBusy=true;const visible=cockpit.visible;cockpit.visible=true;let promise;try{promise=renderer.compileAsync(scene,camera);}finally{cockpit.visible=visible;}promise.catch(()=>{}).finally(()=>warmBusy=false);}


// Story adapter: all aircraft commands feed the same campaign flight controller.
