function updateStoryHUD(){const el=$('#storyLinkHUD');if(!el)return;el.hidden=!started||paused||!!flightSession||introQuiet(s);if(el.hidden)return;syncStoryCampaign(s);const unread=STORY_BEATS.filter(b=>b.when(s)&&!s.story.read.includes(b.id)).length;el.textContent='U / FIELD LINK'+(unread?' · '+unread+' NEW':'');}
function storyTravelReady(strict=false){
 if(!strict&&s.story?.mode!=='story')return true;
 const active=Object.entries(syncSquad(s)).filter(([id,r])=>storyOwns(s,id)&&!storyStation(s,id)&&(r.system.mode!=='DOCK'||hasLiveTask(r)));
 if(active.length){toast('Dock your travelling aircraft or place them at a station before changing sectors.');return false;}return true;
}
function travelStorySector(leg){
 if(![1,2,3].includes(leg)||leg===s.leg||leg===2&&!s.won||leg===3&&!s.leg2Won)return {ok:false,reason:'Clear the route to this sector first.'};
 if(!FIELD_STATIONS.some(p=>p.leg===s.leg&&storyFlag(s,p.requires)&&dist(p.x,p.z)<20)||s.mode==='drone'||Math.abs(s.speed)>.5)return {ok:false,reason:'Stop at an unlocked field station to ride between sectors.'};
 if(!storyTravelReady(true))return {ok:false,reason:'Dock travelling aircraft before departure.'};if(s.battery<8)return {ok:false,reason:'This journey needs 8% bike charge.'};
 releaseDroneView();suspendFleetPolicy(s,'sector travel');s.battery-=8;s.leg=leg;s.intro=completedIntro();s.mode='foot';s.speed=0;s.generator='off';s.harvesting=null;s.swarmOps.program.running=false;s.swarmOps.program.enabled=false;s.swarmOps.program.activeIds=[];s.story.finale.active=false;fleetLaunchQueue=[];
 const z=leg===1?-75:leg===2?-1785:-3740;s.pos.set(leg===3?-30:35,1.7,z);bike.position.set(s.pos.x-3,heightAt(s.pos.x-3,z),z);trailer.position.set(bike.position.x,bike.position.y,z+3.4);s.pos.y=heightAt(s.pos.x,z)+1.7;s.trailerAttached=true;s.yaw=0;bike.rotation.y=trailer.rotation.y=0;
 for(const [id,r]of Object.entries(s.squad))if(!storyStation(s,id)){r.system.pos=droneHome();r.system.hold=droneHome();r.task=null;r.swarmOrder=null;}
 nearest=null;writeSave('auto',true);hud();play();return {ok:true,reason:'Sector '+leg+' reached. Stationed aircraft remain at their saved locations.'};
}
function launchStoryFinale(){
 if(!s.leg3Won)return {ok:false,reason:'Complete the Black Start transmission first.'};
 syncSquad(s);const ids=finaleRoster(s).filter(id=>s.squad[id].battery>=20&&s.squad[id].system.hp>=30&&['DOCK','FOLLOW','HOLD','ORBIT'].includes(s.squad[id].system.mode));
 if(!ids.length)return {ok:false,reason:'Recall and recharge at least one surviving aircraft. Show flight needs 20% battery and 30% hull.'};
 const p=createSwarmProgram();p.ids=ids;p.fleetIds=[...STORY_IDS];p.settings={...p.settings,shape:'ring',height:26,spacing:18,moveZ:-38,origin:'bike',pattern:'orbit',field:'wave',strength:5,show:'dance',beatSync:true,bpm:96};
 const reason=applyLiveSwarmProgram(p);const cast=[...s.swarmOps.program.activeIds];if(!cast.length)return {ok:false,reason};
 s.story.finale={runs:s.story.finale.runs+1,participants:cast,active:true};swarmProgramOwner=s;swarmProgramDraft=JSON.parse(JSON.stringify(s.swarmOps.program));
 radio('CHARGER: '+cast.length+' lights. Every one of them yours.');play();return {ok:true,reason:'Your fleet show is airborne. Open Program swarm to draw or script the next movement.'};
}
